import io

# Check what BufferedWriter does when wrapping
class MyWriter:
    def __init__(self, raw):
        self.raw = raw

    def write(self, data):
        print(f'MyWriter.write called with {type(data).__name__}: {data}')
        return self.raw.write(data)

    def flush(self):
        return self.raw.flush()

bw = io.BufferedWriter(MyWriter(io.BytesIO()))
print('BufferedWriter.write result:', bw.write(b'hello'))
"

