def seek(self, pos, mode=0):
    """Traverse from offset to the specified codepoint"""
    self._checkClosed()
    # Seek to position from the start of the file
    if mode == os.SEEK_SET:
        if pos < 0:
            raise ValueError("negative seek position: {}".format(pos))
        saved_pos = self.tell()
        try:
            self.buffer.seek(0)
            self._traverse_codepoints(0, pos)
            self._tell = pos
        except Exception:
            self._tell = saved_pos
            raise
    # Seek to new position relative to current position
    elif mode == os.SEEK_CUR:
        if pos < 0 and self._tell + pos < 0:
            raise ValueError(
                "negative seek position ({})".format(pos)
            )
        start_pos = self.tell()
        try:
            if pos >= 0:
                self._traverse_codepoints(self.tell(), pos)
            else:
                # Backwards seek: seek buffer to byte position for _tell+pos
                self._seek_to_codepoint(self.tell() + pos)
            self._tell = start_pos + pos
        except Exception:
            self._tell = start_pos
            raise
    elif mode == os.SEEK_END:
        dest_position = self.len - pos
        if dest_position < 0:
            raise ValueError(
                "negative seek position ({})".format(pos)
            )
        self.buffer.seek(0)
        self._traverse_codepoints(0, dest_position)
        self._tell = dest_position
    else:
        raise ValueError(
            f"Invalid whence ({mode}, should be 0, 1, or 2)"
        )
    return self.tell()

def _seek_to_codepoint(self, target_cp):
    """Seek the internal buffer to the byte position corresponding to
    the given codepoint index."""
    if target_cp < 0:
        target_cp = 0
    if target_cp == 0:
        self.buffer.seek(0)
        return
    pos = self.buffer.tell()
    self.buffer.seek(0)
    remaining = target_cp
    while remaining > 0:
        chunk = self.buffer.read(min(remaining, READ_CHUNK_SIZE))
        if not chunk:
            break
        remaining -= len(chunk)
    if self.buffer.tell() > 0:
        self.buffer.seek(0)
        self._traverse_codepoints(0, target_cp)
    self.buffer.seek(self.buffer.tell() - 0)

